flex-centro:
display: flex;
align-items: center;
justify-content: center;

pila:
display: flex;
flex-direction: column;
gap: var(--xb-space-m, 1rem);

fila:
display: flex;
flex-wrap: wrap;
align-items: center;
gap: var(--xb-space-s, 0.75rem);

fila-spaziata:
display: flex;
flex-wrap: wrap;
align-items: center;
justify-content: space-between;
gap: var(--xb-space-s, 0.75rem);

griglia-auto:
display: grid;
gap: var(--xb-space-m, 1rem);
grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--xb-grid-min, 14rem)), 1fr));

griglia-2:
display: grid;
gap: var(--xb-grid-gap, var(--xb-space-m, 1rem));
grid-template-columns: repeat(auto-fit, minmax(min(100%, max(var(--xb-grid-min, 14rem), calc((100% - 1 * var(--xb-grid-gap, var(--xb-space-m, 1rem))) / 2))), 1fr));

griglia-3:
display: grid;
gap: var(--xb-grid-gap, var(--xb-space-m, 1rem));
grid-template-columns: repeat(auto-fit, minmax(min(100%, max(var(--xb-grid-min, 14rem), calc((100% - 2 * var(--xb-grid-gap, var(--xb-space-m, 1rem))) / 3))), 1fr));

griglia-4:
display: grid;
gap: var(--xb-grid-gap, var(--xb-space-m, 1rem));
grid-template-columns: repeat(auto-fit, minmax(min(100%, max(var(--xb-grid-min, 14rem), calc((100% - 3 * var(--xb-grid-gap, var(--xb-space-m, 1rem))) / 4))), 1fr));

contenitore:
inline-size: 100%;
max-inline-size: calc(var(--xb-width-content, 72rem) + 2 * var(--xb-gutter, 1rem));
margin-inline: auto;
padding-inline: var(--xb-gutter, 1rem);

scorri-orizzontale:
display: flex;
gap: var(--xb-space-m, 1rem);
overflow-x: auto;
scroll-snap-type: x mandatory;
overscroll-behavior-x: contain;
& > * {
  flex: 0 0 auto;
  scroll-snap-align: start;
}

sovrapposizione:
position: relative;
isolation: isolate;
&::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: var(--xb-overlay, oklch(0% 0 0 / 0.5));
}

link-esteso:
position: relative;
& a::after {
  content: "";
  position: absolute;
  inset: 0;
}

tronca:
overflow: hidden;
text-overflow: ellipsis;
white-space: nowrap;

testo-gradiente:
background: linear-gradient(90deg, var(--xb-primary, currentColor), var(--xb-accent, currentColor));
-webkit-background-clip: text;
background-clip: text;
color: transparent;

titolo:
font-family: var(--xb-font-heading, inherit);
font-weight: var(--xb-heading-weight, 700);
line-height: var(--xb-leading-tight, 1.15);
color: var(--xb-heading, inherit);
text-wrap: balance;

card:
padding: var(--xb-space-l, 1.5rem);
border: var(--xb-border-width, 1px) solid var(--xb-border, color-mix(in srgb, currentColor 15%, transparent));
border-radius: var(--xb-radius-l, 1rem);
background-color: var(--xb-surface, transparent);
box-shadow: var(--xb-shadow-s, none);

solleva:
transition: transform var(--xb-transition, 150ms ease), box-shadow var(--xb-transition, 150ms ease);
&:hover {
  transform: translateY(-2px);
  box-shadow: var(--xb-shadow-l, 0 12px 32px oklch(0% 0 0 / 0.14));
}

vetro:
background-color: color-mix(in oklch, var(--xb-surface, white) 70%, transparent);
-webkit-backdrop-filter: blur(12px);
backdrop-filter: blur(12px);

pulsante-reset:
appearance: none;
padding: 0;
border: 0;
background: none;
color: inherit;
font: inherit;
cursor: pointer;

nascosto-accessibile:
position: absolute !important;
inline-size: 1px;
block-size: 1px;
padding: 0;
margin: -1px;
overflow: hidden;
clip: rect(0, 0, 0, 0);
white-space: nowrap;
border: 0;

transizione:
transition-property: color, background-color, border-color, box-shadow, transform, opacity;
transition-duration: 150ms;
transition-timing-function: ease;

griglia-5:
display: grid;
gap: var(--xb-grid-gap, var(--xb-space-m, 1rem));
grid-template-columns: repeat(auto-fit, minmax(min(100%, max(var(--xb-grid-min, 14rem), calc((100% - 4 * var(--xb-grid-gap, var(--xb-space-m, 1rem))) / 5))), 1fr));

griglia-6:
display: grid;
gap: var(--xb-grid-gap, var(--xb-space-m, 1rem));
grid-template-columns: repeat(auto-fit, minmax(min(100%, max(var(--xb-grid-min, 14rem), calc((100% - 5 * var(--xb-grid-gap, var(--xb-space-m, 1rem))) / 6))), 1fr));

griglia-1-2:
display: grid;
gap: var(--xb-space-m, 1rem);
grid-template-columns: 1fr;
@media (width >= 48em) {
  grid-template-columns: 1fr 2fr;
}

griglia-2-1:
display: grid;
gap: var(--xb-space-m, 1rem);
grid-template-columns: 1fr;
@media (width >= 48em) {
  grid-template-columns: 2fr 1fr;
}

griglia-1-3:
display: grid;
gap: var(--xb-space-m, 1rem);
grid-template-columns: 1fr;
@media (width >= 48em) {
  grid-template-columns: 1fr 3fr;
}

griglia-3-1:
display: grid;
gap: var(--xb-space-m, 1rem);
grid-template-columns: 1fr;
@media (width >= 48em) {
  grid-template-columns: 3fr 1fr;
}

griglia-contenuto:
display: grid;
grid-template-columns: [piena-start] minmax(var(--xb-gutter, 1rem), 1fr) [contenuto-start] min(100% - 2 * var(--xb-gutter, 1rem), var(--xb-width-content, 72rem)) [contenuto-end] minmax(var(--xb-gutter, 1rem), 1fr) [piena-end];
& > * {
  grid-column: contenuto;
}
& > .piena {
  grid-column: piena;
}

flex-griglia:
display: flex;
flex-wrap: wrap;
gap: var(--xb-space-m, 1rem);
& > * {
  flex: 1 1 var(--xb-grid-min, 14rem);
}

divisori:
& > * + * {
  border-block-start: var(--xb-border-width, 1px) solid var(--xb-border, currentColor);
  padding-block-start: var(--xb-space-m, 1rem);
}

divisori-orizzontali:
& > * + * {
  border-inline-start: var(--xb-border-width, 1px) solid var(--xb-border, currentColor);
  padding-inline-start: var(--xb-space-m, 1rem);
}

sfondo-elemento:
position: absolute;
inset: 0;
z-index: -1;
inline-size: 100%;
block-size: 100%;
object-fit: cover;

raggio-concentrico:
--raggio-esterno: var(--xb-radius-l, 1rem);
--spazio: var(--xb-space-s, 0.75rem);
border-radius: var(--raggio-esterno);
padding: var(--spazio);
& > * {
  border-radius: max(0px, calc(var(--raggio-esterno) - var(--spazio)));
}

nastro-angolo:
position: relative;
overflow: hidden;
& > .nastro {
  position: absolute;
  inset-block-start: 1.25rem;
  inset-inline-end: -2.5rem;
  padding: 0.25rem 3rem;
  transform: rotate(45deg);
  background: var(--xb-accent, #888);
  color: var(--xb-on-accent, white);
  font-size: var(--xb-text-s, 0.875rem);
}

suggerimento:
position: relative;
&::after {
  content: attr(data-suggerimento);
  position: absolute;
  inset-block-end: calc(100% + 0.5rem);
  inset-inline-start: 50%;
  translate: -50% 0;
  padding: 0.25rem 0.5rem;
  border-radius: var(--xb-radius-s, 0.25rem);
  background: var(--xb-text, black);
  color: var(--xb-bg, white);
  font-size: var(--xb-text-s, 0.875rem);
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 150ms ease;
}
&:hover::after,
&:focus-visible::after {
  opacity: 1;
}

link-salta:
position: absolute;
inset-block-start: 0;
inset-inline-start: 0;
padding: 0.5rem 1rem;
background: var(--xb-bg, white);
translate: 0 -100%;
&:focus-visible {
  translate: 0 0;
}
